CREATE TABLE IF NOT EXISTS compliance_records (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), compliance_type TEXT NOT NULL, licence_number TEXT, licence_type TEXT, issue_date TEXT, expiry_date TEXT, status TEXT NOT NULL, recommendations_json TEXT, corrective_actions_json TEXT, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS compliance_inspections (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), compliance_id TEXT NOT NULL REFERENCES compliance_records(id), inspected_at TEXT NOT NULL, rating TEXT, recommendations_json TEXT, corrective_actions_json TEXT, inspector TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS managed_documents (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), document_number TEXT NOT NULL, category TEXT NOT NULL, title TEXT NOT NULL, entity_id TEXT, storage_key TEXT NOT NULL, checksum TEXT NOT NULL, version INTEGER NOT NULL, expires_at TEXT, access_roles_json TEXT, verification_code TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, UNIQUE(school_id, document_number), UNIQUE(school_id, verification_code));
CREATE TABLE IF NOT EXISTS document_versions (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), document_id TEXT NOT NULL REFERENCES managed_documents(id), version INTEGER NOT NULL, checksum TEXT NOT NULL, expires_at TEXT, updated_by TEXT NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS privacy_consents (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), subject_id TEXT NOT NULL, purpose TEXT NOT NULL, granted INTEGER NOT NULL, recorded_by TEXT NOT NULL REFERENCES users(id), recorded_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS privacy_requests (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), request_type TEXT NOT NULL, subject_id TEXT NOT NULL, details TEXT, status TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS retention_policies (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), data_category TEXT NOT NULL, retention_period TEXT NOT NULL, action_after_expiry TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS data_protection_officers (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), user_id TEXT NOT NULL REFERENCES users(id), designation TEXT NOT NULL, appointed_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS data_breaches (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), discovered_at TEXT NOT NULL, description TEXT NOT NULL, severity TEXT NOT NULL, containment TEXT, status TEXT NOT NULL, reported_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_compliance_expiry ON compliance_records(school_id, expiry_date);
CREATE INDEX IF NOT EXISTS idx_documents_category ON managed_documents(school_id, category, expires_at);
CREATE INDEX IF NOT EXISTS idx_privacy_requests_subject ON privacy_requests(school_id, subject_id, status);
